import{_ as d,C as n,o as r,c as l,j as t,a as o,E as i,a2 as s}from"./chunks/framework.D0xy3_1I.js";const x=JSON.parse('{"title":"Art and audio","description":"","frontmatter":{},"headers":[],"relativePath":"gdd/art-audio.md","filePath":"gdd/art-audio.md"}'),h={name:"gdd/art-audio.md"},c={id:"a-1-current-state",tabindex:"-1"},p={id:"a-4-animation-and-expressions-wanted-from-the-artist",tabindex:"-1"},u={id:"a-6-audio",tabindex:"-1"};function g(f,e,b,m,y,w){const a=n("Badge");return r(),l("div",null,[e[9]||(e[9]=t("h1",{id:"art-and-audio",tabindex:"-1"},[o("Art and audio "),t("a",{class:"header-anchor",href:"#art-and-audio","aria-label":'Permalink to "Art and audio"'},"​")],-1)),t("h2",c,[e[0]||(e[0]=o("A.1 Current state ",-1)),i(a,{type:"tip",text:"Live"}),e[1]||(e[1]=o()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#a-1-current-state","aria-label":'Permalink to "A.1 Current state <Badge type="tip" text="Live" />"'},"​",-1))]),e[10]||(e[10]=s('<ul><li><strong>Fish:</strong> 49 species, each a 3D model (<code>public/models/fish/&lt;name&gt;/</code>: one <code>model.fbx</code> and one <code>tex.jpg</code>). The body wave and the blink are done in code. The colour copies used as look-alikes are made from the same texture by turning its colours (<a href="./rules#_3-2-fish">Rules 3.2</a>).</li><li><strong>Artist models in the tank:</strong> the octopus, the jellyfish, the clam, the clay pot, the stone pillars and statue, the anchor, the three corals and the glass bottle (<code>public/models/&lt;name&gt;/</code>, one <code>model.fbx</code> and one <code>tex.png</code> each). The source files are in <code>Fish Asset 3D/</code>.</li><li><strong>Still built in code, as placeholders:</strong> rocks, houses, arches, seaweed, anemones, the treasure chest, the wreck, barrels, the Atlantis crystals and sea seeds, the pump tube, the food bucket and the pearl.</li><li><strong>UI:</strong> drawn by Phaser from pictures: the pop-ups (Pause, Out of space, Purchase, Well Done, Level failed), buttons, ribbons, icons and the progress bar are in <code>public/ui/bf/</code> and <code>public/ui/new/</code>; the target tanks, the Backup and the cage are in <code>public/ui/tanks/</code>; the loading screen and the logo are in <code>public/ui/load/</code>. The font is Lilita One. The Levels pop-up (the level grid) is still the older, plain HTML look. The art in <code>public/ui/bf/</code> came from the sister project; it can be replaced piece by piece.</li><li><strong>Look:</strong> a round or shaped tank (6 shapes) in a 3D aquarium hall (6 looks), glass and water bending the view through a post-process lens, a rippling surface, light rays, bubbles, confetti and a curtain between levels.</li><li><strong>Logo:</strong> <code>Added Assets/Game logo.png</code> (cut and resized to <code>public/ui/load/logo.png</code>), shown on the loading screen with a wave and a light sweep.</li></ul><h2 id="a-2-3d-fish-what-a-new-fish-needs" tabindex="-1">A.2 3D fish: what a new fish needs <a class="header-anchor" href="#a-2-3d-fish-what-a-new-fish-needs" aria-label="Permalink to &quot;A.2 3D fish: what a new fish needs&quot;">​</a></h2><ul><li>The fish are 49 models in <code>public/models/fish/</code> (source: <code>Fish Asset 3D/3D model</code>). <strong>For a new fish:</strong> one mesh, one texture, the eyes drawn on the texture with a dark pupil and a white highlight, the nose to +x or +z (list the file in <code>FACES_Z</code> if it faces z), then run <code>scripts/prep-fish.py</code>: it copies every fish from <code>Fish Asset 3D/3D model</code> into <code>public/models/fish/</code> and writes <code>public/models/fish/list.json</code>.</li><li>A fish covers only a few dozen pixels on screen, so <strong>big eyes, contrasting colours and a readable shape</strong> matter more than fine detail. The game finds the eye on the texture for the blink; if it is unclear the blink does not show (a position can be given by hand in <code>EYE_AT</code>).</li><li>The dark outline is generated from the fish&#39;s own colour. <strong>Do not paint a black outline.</strong></li><li>Keep species clearly different in shape and colour: wrong fish include colour copies of targets, so already-similar originals make levels unfair.</li><li>The old Unity set, <code>blue_white_babe</code> and the 2D pictures are gone.</li></ul><h2 id="a-3-decoration-models" tabindex="-1">A.3 Decoration models <a class="header-anchor" href="#a-3-decoration-models" aria-label="Permalink to &quot;A.3 Decoration models&quot;">​</a></h2><ul><li>Put the source in <code>Fish Asset 3D/Decoration/&lt;Name&gt;/</code> (an <code>.fbx</code> and its <code>.png</code>), copy it to <code>public/models/&lt;name&gt;/model.fbx</code> with the texture resized to 1024 px as <code>tex.png</code>, and add the piece to a theme in <code>game/src/main.js</code> with <code>loadDecorModel(&#39;&lt;name&gt;&#39;)</code> (the model is scaled to a height you give, stands on the floor and is lit by its own texture).</li><li>Solid pieces are laid out so they never overlap each other or stick out through the glass; a piece that cannot fit in a small tank is left out. A piece made of parts should have a simple shape (the collision box comes from its size; a tilted long part makes a huge box). See <a href="./rules#_3-8-collision-and-layout">Rules 3.8</a>.</li><li>Decoration in real planted aquariums is mostly few and large pieces (rock, driftwood, big plants), while a themed cartoon tank carries more. A crowded tank is where overlap and jitter bugs start, so every new piece should be checked at a small tank shape.</li></ul>',5)),t("h2",p,[e[3]||(e[3]=o("A.4 Animation and expressions wanted from the artist ",-1)),i(a,{type:"warning",text:"Coming soon"}),e[4]||(e[4]=o()),e[5]||(e[5]=t("a",{class:"header-anchor",href:"#a-4-animation-and-expressions-wanted-from-the-artist","aria-label":'Permalink to "A.4 Animation and expressions wanted from the artist <Badge type="warning" text="Coming soon" />"'},"​",-1))]),e[11]||(e[11]=s('<p>None of this is integrated yet. Everything else (bounce on spawn, shake on touch, flying into the tray, bubbles, ink, light rays, water splashes, schooling, biting the food) is done in code.</p><p><strong>Loop clips (30 fps, in place):</strong></p><table tabindex="0"><thead><tr><th>Clip</th><th>Description</th></tr></thead><tbody><tr><td>Swim</td><td>S-shaped body bend, fanned tail, pectoral fins flapping, seamless loop. Code scales playback speed, so one clip is enough</td></tr><tr><td>Hover</td><td>Almost still, only pectoral fins and tail move slightly</td></tr></tbody></table><p><strong>5 face expressions (blendshape or face texture swap):</strong></p><table tabindex="0"><thead><tr><th>Expression</th><th>Eyes</th><th>Mouth</th><th>Fins / body</th><th>Used when</th></tr></thead><tbody><tr><td>Neutral</td><td>Medium, round, pupil centred, blink (~0.2 s, every 2-5 s)</td><td>Closed, corners slightly up</td><td>Relaxed</td><td>Normal</td></tr><tr><td>Happy</td><td>Curved ^ ^ (or big round with highlight), slightly puffed cheeks</td><td>Wide smile, may be open</td><td>Pectoral fins slightly up</td><td>Correct fish, celebration</td></tr><tr><td>Scared</td><td>Very big round, tiny pupil</td><td>Crooked, small open, trembling</td><td>Fins stiff upright, body tucked</td><td>Near jellyfish / octopus, tapped, pushed from tube</td></tr><tr><td>Sad</td><td>Big, outer corners drooping, pupil looking down</td><td>Closed, curved down</td><td>Fins drooping, tail low</td><td>Wrong tap, sent to Backup</td></tr><tr><td>Surprised</td><td>Big round, tiny pupil, lid fully open</td><td>Round O</td><td>Fins slightly spread</td><td>Just spawned, caught, startled by a falling object</td></tr></tbody></table><p>Optional if time allows: <strong>Dizzy</strong> (swirl eyes, covered in ink) and <strong>Eating</strong> (a chewing mouth: the fish bite the food but have no chewing animation yet).</p><p>Convention: keep the same bone names and the same eye and mouth positions across species so code can share logic.</p><h2 id="a-5-other-art-to-consider" tabindex="-1">A.5 Other art to consider <a class="header-anchor" href="#a-5-other-art-to-consider" aria-label="Permalink to &quot;A.5 Other art to consider&quot;">​</a></h2><ul><li>Real models for the pearl, the food bucket, the pump tube, and the code-built decoration listed in A.1.</li><li>A new UI kit, so <code>public/ui/bf/</code> can be retired; the Levels pop-up in the new style.</li><li>App icon and store images.</li></ul>',9)),t("h2",u,[e[6]||(e[6]=o("A.6 Audio ",-1)),i(a,{type:"tip",text:"Live"}),e[7]||(e[7]=o()),e[8]||(e[8]=t("a",{class:"header-anchor",href:"#a-6-audio","aria-label":'Permalink to "A.6 Audio <Badge type="tip" text="Live" />"'},"​",-1))]),e[12]||(e[12]=t("p",null,[o("Sound is recorded files in "),t("code",null,"public/sfx/"),o(" (38 effects and the music "),t("code",null,"bgm_ap"),o(", as "),t("code",null,".m4a"),o("), played through WebAudio. A sound without a file does not play (the old synthesised bleeps are gone). The music restarts with every level, ducks to half while a pop-up is open and fades out when the win or lose screen comes. See "),t("a",{href:"./sounds"},"Sounds"),o(" for which sound plays when.")],-1)),e[13]||(e[13]=t("p",null,[t("strong",null,"Missing sounds:"),o(" the swarm, the squabble and conga events, fish biting the food, the jellyfish, the bounty tanks, the camera and the tank shape change.")],-1))])}const A=d(h,[["render",g]]);export{x as __pageData,A as default};
